import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const fontsCssUrl = new URL("./fonts.css", import.meta.url);
const fontsCss = readFileSync(fileURLToPath(fontsCssUrl), "utf8");
const indexHtml = readFileSync(fileURLToPath(new URL("../../index.html", import.meta.url)), "utf8");

/**
 * The font declarations are generated by hand, so a renamed file, a dropped
 * preload or a reintroduced Google Fonts link would otherwise fail silently as
 * an invisible fallback typeface.
 */
describe("self-hosted font pipeline", () => {
  it("declares both families as variable faces", () => {
    expect(fontsCss).toContain('font-family: "Space Grotesk"');
    expect(fontsCss).toContain('font-family: "Inter"');
    expect(fontsCss).toMatch(/font-weight:\s*\d+\s+\d+;/);
  });

  it("points every face at a font file that exists", () => {
    const urls = [...fontsCss.matchAll(/url\("([^"]+)"\)/g)].map((match) => match[1]);
    expect(urls.length).toBeGreaterThanOrEqual(4);

    for (const url of urls) {
      expect(existsSync(fileURLToPath(new URL(url, fontsCssUrl)))).toBe(true);
    }
  });

  it("keeps subsets lazy rather than blocking text", () => {
    expect(fontsCss).toContain("font-display: swap");
    expect(fontsCss).not.toContain("font-display: block");
    expect(fontsCss).toMatch(/unicode-range:/);
  });

  it("never reintroduces a third-party font origin", () => {
    expect(indexHtml).not.toContain("fonts.googleapis.com");
    expect(indexHtml).not.toContain("fonts.gstatic.com");
  });
});
